/* Chart presentation, navigation and transition lists; no natal formula changes. */
(()=>{'use strict';const $=id=>document.getElementById(id);let busy=false,transitionDialog,transitionVersion=0;
const decorate=window.KPQuickTools?.decorate;if(decorate)window.KPQuickTools.decorate=function(button,tab,name){decorate(button,tab,name);const label=button.querySelector('.kp-quick-label');if(label)label.textContent=name;};
function menu(){for(const button of document.querySelectorAll('.kp-quick-tools button[data-quick-function]')){const title=button.getAttribute('aria-label');const label=button.querySelector('.kp-quick-label');if(label&&title&&label.textContent!==title)label.textContent=title;}document.querySelector('.kp-quick-tools')?.setAttribute('aria-label','KP Master menu');}
function legend(){document.querySelectorAll('.kp-chart-readable').forEach(n=>n.remove());}
function colours(){const pane=$('settings-pane-astrologer');if(!pane||$('kp-chart-colours-link'))return;const box=document.createElement('section');box.id='kp-chart-colours-link';box.innerHTML='<h4>Chart colours and text</h4><p>Choose planet colours, chart font size and bold text.</p>';for(const [name,tab]of [['Planet colours','themes'],['Chart font size','display']]){const b=document.createElement('button');b.type='button';b.textContent=name;b.onclick=()=>{$('settings-tab-'+tab)?.click();const field=$(tab==='themes'?'setting-planetColorSu':'setting-fontSize');field?.scrollIntoView({block:'center'});field?.focus();};box.append(b);}const grid=document.createElement('div');grid.className='kp-astro-chart-colours';for(const id of ['Su','Mo','Ma','Me','Ju','Ve','Sa','Ra','Ke']){const original=$('setting-planetColor'+id);if(!original)continue;const label=document.createElement('label');label.textContent=(window.KPDisplay?.names[id]||id)+' colour';const input=document.createElement('input');input.type='color';input.value=original.value;input.id='kp-astro-colour-'+id;input.addEventListener('input',()=>{original.value=input.value;original.dispatchEvent(new Event('input',{bubbles:true}));original.dispatchEvent(new Event('change',{bubbles:true}));});original.addEventListener('input',()=>input.value=original.value);label.append(input);grid.append(label);}box.append(grid);pane.append(box);$('settings-tab-astrologer')?.addEventListener('click',()=>{for(const id of ['Su','Mo','Ma','Me','Ju','Ve','Sa','Ra','Ke']){const n=$('kp-astro-colour-'+id),source=$('setting-planetColor'+id);if(n&&source)n.value=source.value;}});}
function printable(title,body){const w=window.open('','_blank');if(!w)return;w.document.open();w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>'+title+'</title><style>@page{size:A4;margin:12mm}body{font:12px Arial;color:#17364c;margin:0}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #a8b8c5;padding:7px;overflow-wrap:anywhere}thead{display:table-header-group}tr{break-inside:avoid}button{padding:10px}@media print{button{display:none}}</style></head><body><button onclick="print()">Print / Save PDF</button><h2>'+title+'</h2>'+body+'</body></html>');w.document.close();}
function isNatalAvailable(){return $('instant-prashna')?.value!=='1'&&(!$("chart-kind")?.value||$("chart-kind").value==='natal')&&Boolean(window.currentKPModel?.ready);}
function natalOnlyMessage(){return window.KPPreferences?.get?.().language==='marathi'?'प्रथम जन्मकुंडली उघडा. हा पर्याय फक्त जन्मकुंडलीसाठी आहे.':'Open a natal horoscope first. This tool is available only for the natal chart.';}
function syncNatalAvailability(){const allowed=isNatalAvailable(),button=$('kp-asc-moon-tool');if(button)button.hidden=!allowed;if(transitionDialog){transitionDialog.querySelector('[data-find]').disabled=!allowed||busy;transitionDialog.querySelector('[data-print]').disabled=!allowed;if(!allowed){transitionVersion++;if(busy)window.KPTransit?.cancel?.();transitionDialog.querySelector('[data-status]').textContent=natalOnlyMessage();transitionDialog.querySelector('[data-results]').replaceChildren();}}}
async function transitions(){if(!isNatalAvailable())return false;if(!transitionDialog){transitionDialog=document.createElement('dialog');transitionDialog.className='kp-cusp-dialog';transitionDialog.innerHTML='<h2>Ascendant / Moon transitions</h2><div class="kp-transition-tools kp-transition-actions"><button data-find>Preview</button><button data-print>Print</button><button data-pdf>Export to PDF</button><button data-close>Close</button></div><p class="kp-transition-prompt">Please select the point and combination</p><div class="kp-transition-choices"><fieldset><label><input type="radio" name="transition-body" value="As" checked>Lagna</label><label><input type="radio" name="transition-body" value="Mo">Moon</label></fieldset><fieldset><label><input type="radio" name="transition-level" value="star" checked>Nakshatra</label><label><input type="radio" name="transition-level" value="sub">Sub lord</label></fieldset></div><select data-body hidden><option value="As">Ascendant · 24 hours from birth</option><option value="Mo">Moon · 30 days from birth</option></select><select data-level hidden><option value="star">Nakshatra</option><option value="sub">Sub lord</option></select><p data-status>Starting at the natal birth date and time, using the birth location.</p><div data-results></div>';document.body.append(transitionDialog);transitionDialog.querySelector('[data-close]').onclick=()=>{transitionVersion++;if(busy)KPTransit.cancel();transitionDialog.close();};transitionDialog.querySelector('[data-find]').onclick=find;for(const input of transitionDialog.querySelectorAll('input[type=radio]'))input.onchange=()=>{transitionDialog.querySelector(input.name==='transition-body'?'[data-body]':'[data-level]').value=input.value;};transitionDialog.querySelector('[data-pdf]').onclick=()=>transitionDialog.querySelector('[data-print]').click();transitionDialog.querySelector('[data-print]').onclick=()=>printable('Ascendant / Moon transitions','<p>'+transitionDialog.querySelector('[data-status]').textContent+'</p>'+transitionDialog.querySelector('[data-results]').innerHTML);}
transitionDialog.querySelector('[data-results]').replaceChildren();transitionDialog.querySelector('[data-status]').textContent='Natal birth: '+$('dob').value+' '+$('birthTime').value+' · '+$('lat').value+' / '+$('lon').value;transitionDialog.showModal();}
async function find(){if(busy)return;busy=true;const d=transitionDialog,button=d.querySelector('[data-find]'),status=d.querySelector('[data-status]');button.disabled=true;try{if(!isNatalAvailable())throw Error(natalOnlyMessage());const run=++transitionVersion,planet=d.querySelector('[data-body]').value,level=d.querySelector('[data-level]').value,native=KPHorary.nativeMoment(),start=new Date(native.date),end=new Date(start.getTime()+(planet==='As'?1:30)*86400000),tracks=[];const lords=['Ke','Ve','Su','Mo','Ma','Ra','Ju','Sa','Me'];for(let n=0;n<27;n++)for(const lord of level==='sub'?lords:[null])tracks.push({id:n+':'+lord,planet,label:'',levels:[level],test:p=>p.nakIndex===n&&(!lord||p.sl===lord)});const rows=await KPTransit.scan({start,end,tracks,location:native,shouldCancel:()=>run!==transitionVersion||!isNatalAvailable(),onProgress:p=>status.textContent='Searching… '+Math.round(p*100)+'%'}),offset=KPHomeDasha.getData().timeZoneHours*3600000;if(run!==transitionVersion||!isNatalAvailable())throw Error(natalOnlyMessage());const table=document.createElement('table');table.className='kp-feature-table';table.innerHTML='<thead><tr><th>Combination · sign / star / sub</th><th>Entry · local time</th><th>Longitude</th></tr></thead><tbody></tbody>';for(const row of rows.filter(r=>!r.startClipped)){const date=new Date(Date.parse(row.start)+1500),lon=planet==='As'?KPTransitHouses.ascendant(date,native.latitude,native.longitude):KPEphemeris.longitude(date,planet),p=KPDisplay.longitudeDetails(lon*3600),tr=document.createElement('tr');for(const value of [p.sgl+' / '+p.stl+' / '+p.sl,new Date(Date.parse(row.start)+offset).toISOString().replace('T',' ').slice(0,19),lon.toFixed(6)+'°']){const td=document.createElement('td');td.textContent=value;tr.append(td);}table.tBodies[0].append(tr);}d.querySelector('[data-results]').replaceChildren(table);status.textContent=table.tBodies[0].rows.length+' transitions · From '+new Date(start.getTime()+offset).toISOString().replace('T',' ').slice(0,19)+' · natal chart local time · boundary precision 1 second.';}catch(e){status.textContent=e.message;}finally{busy=false;button.disabled=!isNatalAvailable();}}
function init(){menu();colours();const bar=document.querySelector('#south9 .kundali-toolbar');if(bar){const b=document.createElement('button');b.id='kp-asc-moon-tool';b.textContent='Ascendant / Moon transitions';b.onclick=transitions;bar.append(b);}syncNatalAvailability();for(const event of ['chart-saved','chart-manual-change','kp-preferences-changed','kp-ephemeris-ready'])window.addEventListener(event,syncNatalAvailability);document.addEventListener('change',e=>{if(['chart-kind','instant-prashna','dob','birthTime','lat','lon'].includes(e.target?.id))syncNatalAvailability();});legend();}
window.KPChartWorkspace=Object.freeze({transitions,printable,isNatalAvailable});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,100));else init();})();
